{
  "units": [
    {
      "issue": "虚构情景中，截至2023-08-01付款及签约事件完成后，A、B、C剩余债务的合法范围、SP-01的清偿归属，以及各保证人和第三人的即时付款责任边界。",
      "decisive_facts": [
        {
          "fact": "A于2022年成立，资金来自套取的银行信贷；实际交付143072.00元。乙已返还20238.00元，双方约定如合同无效，该款全部冲抵财产返还，且不请求其他无效后赔偿。",
          "spans": ["S01", "S02", "S12"]
        },
        {
          "fact": "B于2022-01-12实际交付并成立，票面金额包含预扣利息；实际交付185920.00元，约定年利率13.20%，题设成立时一年期LPR为3.70%。三次结息归档均无新增交付，不构成债务更新。",
          "spans": ["S03", "S04", "S05"]
        },
        {
          "fact": "戊、庚各自承诺向甲保证全部B债务，内部约定相互追偿、各分担50%；二人同意原结息机制，但未书面同意展期。针对戊的给付诉状于2023-07-07送达后撤诉，针对庚的完整给付请求于2023-07-06到达。",
          "spans": ["S06"]
        },
        {
          "fact": "C于2019-02-07实际交付226560.00元并成立，约定年利率23.50%，采用实际自然日/365单利；甲明确请求分段适用利率保护规则，各次起诉时一年期LPR均由题设设为3.25%。",
          "spans": ["S07"]
        },
        {
          "fact": "C有七笔已结算付款。原合同约定费用、合法利息、本金的清偿顺序，但T-02有双方签署的本金优先补充协议；其他本金优先备注只有乙单方作出。T-01的截图与收据属于同一交易，X-01未执行。",
          "spans": ["S08", "S09", "S11"]
        },
        {
          "fact": "己于2022年承诺乙不能履行、无力偿还时才代偿。甲在C到期后六个月内起诉乙、撤诉并再次起诉；截至截日未审判执行。己未放弃先诉抗辩，题设排除了相关例外，其后来签名仅确认收件。",
          "spans": ["S07", "S10"]
        },
        {
          "fact": "SP-01于2023-08-01 09:20到账25000.00元，限定清偿B、C而未具体指定。双方约定：两债均到期且有同等资信全额保证时，先偿付款日依法可强制请求年利率较高的债务；其他情形依法处理。",
          "spans": ["S06", "S10", "S13"]
        },
        {
          "fact": "辛于同日13:40签署的正文要求先对乙追索并执行，不能清偿的部分才由辛支付，明确不免除乙的原债务且保留先诉要求。16:10追加辛为被告；未发生SP-01后的付款或新的现金交付。",
          "spans": ["S14"]
        },
        {
          "fact": "结算不计2023-08-01当日利息，各输出分项最终取分后相加。S12中的外部责任减半、旧保证规则适用、标题决定即时付款及后来文书追溯改变付款归属等内容，均明确属于单方法律主张。",
          "spans": ["S12", "S13", "S14"]
        }
      ],
      "support_spans": {
        "materials": [
          {
            "span_id": "S01",
            "excerpt": "甲把为个人消费用途向银行套取的信贷资金转给乙"
          },
          {
            "span_id": "S02",
            "excerpt": "如A被认定无效，双方同意在清算中全部作为已返还财产冲抵"
          },
          {
            "span_id": "S03",
            "excerpt": "乙于2022-01-12实际收到185920.00元，当日起息，合同也于该日成立"
          },
          {
            "span_id": "S04",
            "excerpt": "双方不另成立债务更新合同，各期沿用最初借据约定的利率与合同成立时LPR"
          },
          {
            "span_id": "S05",
            "excerpt": "B-1，2022-07-06，纸面本金210939.26元，新增交付0.00元。"
          },
          {
            "span_id": "S06",
            "excerpt": "戊、庚各自以连带责任保证向甲覆盖全部B债务"
          },
          {
            "span_id": "S07",
            "excerpt": "甲明确请求按照合同成立至2020-08-19当时的司法解释计算该段利息"
          },
          {
            "span_id": "S08",
            "excerpt": "T-01 / 2019-04-18 / 乙向甲付款25208.00元 / 银行已结算 / 乙指定偿还C号债务。"
          },
          {
            "span_id": "S09",
            "excerpt": "2019-08-23双方又签署仅适用于T-02的补充协议：该笔付款用于清偿本金"
          },
          {
            "span_id": "S10",
            "excerpt": "甲2023-06-14重新对乙起诉C债务，当日有效受理，截至截日未审判"
          },
          {
            "span_id": "S11",
            "excerpt": "X-01未执行，已撤销付款指令，未向甲账户记入该金额"
          },
          {
            "span_id": "S12",
            "excerpt": "以下是最终书面意见中的法律主张，不是双方认可的事实或法院认定"
          },
          {
            "span_id": "S13",
            "excerpt": "以付款日依法可强制请求的年利率比较，先清偿该年利率较高的债务"
          },
          {
            "span_id": "S14",
            "excerpt": "甲应先依法对乙追索C，依法强制执行后仍不能清偿的部分，辛再向甲支付其中全部"
          }
        ],
        "authorities": [
          {
            "source_id": "civil-code-2020",
            "provisions": ["157", "552", "560", "561", "670", "679", "682", "687", "688", "691", "692", "693", "695", "697", "1260"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
          },
          {
            "source_id": "lending-2015",
            "provisions": ["26"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/15146.html"
          },
          {
            "source_id": "lending-2020-12",
            "provisions": ["13", "25", "26", "27", "28", "31"],
            "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
          },
          {
            "source_id": "guarantee-2020",
            "provisions": ["13", "25", "29", "31", "32", "34", "36"],
            "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html"
          }
        ]
      },
      "dependencies": {
        "nodes": [
          {
            "id": "A",
            "issue": "A合同效力、返还范围及丁的合同保证责任",
            "depends_on": [],
            "support_spans": ["S01", "S02", "S12"],
            "rule_refs": ["lending-2020-12:13", "civil-code-2020:157", "civil-code-2020:682"],
            "supported_state": "按题设2022年成立时间和所附规则，套取银行贷款转贷支持合同无效判断，不以高利或乙事先知情为必要条件。清算范围为实际交付减已返还财产；丁不能被要求依无效保证合同履行保证责任，未请求的过错赔偿另行排除。"
          },
          {
            "id": "B_AMOUNT",
            "issue": "B实际本金、合法结息及整体本息上限",
            "depends_on": [],
            "support_spans": ["S03", "S04", "S05", "S06", "S12", "S13"],
            "rule_refs": ["civil-code-2020:670", "civil-code-2020:679", "lending-2020-12:25", "lending-2020-12:26", "lending-2020-12:27", "lending-2020-12:28"],
            "supported_state": "初始本金以185920.00元为基础，纸面借据金额不能替代实际交付及合法结息审核。13.20%约定利率低于题设14.80%的保护上限；仍须逐期复算可计入后期本金的利息，并与最初本金对应的整体上限比较，不将各借据当作独立新增借款。"
          },
          {
            "id": "C_AMOUNT",
            "issue": "C跨版本利率、付款证据及逐笔清偿",
            "depends_on": [],
            "support_spans": ["S07", "S08", "S09", "S11"],
            "rule_refs": ["lending-2015:26", "lending-2020-12:25", "lending-2020-12:28", "lending-2020-12:31", "civil-code-2020:561"],
            "supported_state": "合同成立至2020-08-19的约定23.50%未超过旧规则24%保护标准；自2020-08-20起按题设起诉时LPR四倍即13.00%控制。T-02依双方特别约定本金优先，其余按原合同费用、合法利息、本金顺序处理。T-01仅记一次，X-01不记为实付；未付利息不资本化。旧时期的清偿顺序直接有原合同及补充协议支持，不需追溯适用民法典第561条。"
          },
          {
            "id": "B_GUARANTEE",
            "issue": "戊、庚分别行权、保证存续及内部追偿与外部责任的区别",
            "depends_on": [],
            "support_spans": ["S06", "S12"],
            "rule_refs": ["civil-code-2020:688", "civil-code-2020:692", "civil-code-2020:693", "civil-code-2020:695", "guarantee-2020:13", "guarantee-2020:25", "guarantee-2020:29", "guarantee-2020:31", "guarantee-2020:32"],
            "supported_state": "戊、庚均为全额连带责任保证。还清为止的期间约定不明，未经书面同意的展期不改变保证期间，按原到期日计算至2023-07-12。戊在期间内收到给付诉状，后续撤诉不否定该次行权；庚也独立收到期间内给付请求。因此不存在题设所称因未向庚行权而丧失追偿的前提，内部各50%不将对甲的约定全额保证自动减半。"
          },
          {
            "id": "C_GUARANTEE",
            "issue": "己的保证类型、撤诉再诉效果与先诉抗辩",
            "depends_on": [],
            "support_spans": ["S07", "S10", "S12"],
            "rule_refs": ["civil-code-2020:687", "civil-code-2020:691", "civil-code-2020:692", "civil-code-2020:693", "civil-code-2020:1260", "guarantee-2020:25", "guarantee-2020:31", "guarantee-2020:34"],
            "supported_state": "己的保证成立于2022年，其正文支持一般保证，不能仅因主借款成立于2019年而将保证关系一并按旧规则处理。保证期间至2023-06-15，撤诉后于2023-06-14再次起诉乙，支持保证继续存续。尚未审判执行且无例外，己仍可行使先诉抗辩；仅收件签名不构成新的保证承诺。"
          },
          {
            "id": "SP_ALLOCATION",
            "issue": "09:20付款时B、C之间的清偿归属",
            "depends_on": ["B_AMOUNT", "C_AMOUNT", "B_GUARANTEE", "C_GUARANTEE"],
            "support_spans": ["S06", "S07", "S10", "S13"],
            "rule_refs": ["civil-code-2020:560", "civil-code-2020:561"],
            "supported_state": "应按09:20时既有债务和担保状态适用双方附件。一般保证具有先诉抗辩不等于没有担保；题设支持两债均到期、具有同等资信全额保证。依法可请求的年利率分别为B的13.20%和C的13.00%，因此SP-01优先清偿B；进入B后还须区分利息与本金的抵充，不能直接将25000.00元全部扣减本金。"
          },
          {
            "id": "BALANCES",
            "issue": "SP-01后的债务分项及非重复总额",
            "depends_on": ["A", "B_AMOUNT", "C_AMOUNT", "SP_ALLOCATION"],
            "support_spans": ["S02", "S04", "S07", "S12", "S13", "S14"],
            "rule_refs": ["civil-code-2020:157", "civil-code-2020:561", "lending-2020-12:27", "lending-2020-12:31"],
            "supported_state": "A返还债务不受SP-01影响；B扣除该次有效清偿，C依既有流水结算。应保留各自本金、利息及费用角色，按题设最终分项取分后汇总，不把同一债务的多个责任主体重复计入债权总额。"
          },
          {
            "id": "XIN_DOCUMENT",
            "issue": "13:40第三人文书性质及其时间效力",
            "depends_on": ["BALANCES", "C_GUARANTEE"],
            "support_spans": ["S12", "S13", "S14"],
            "rule_refs": ["civil-code-2020:552", "civil-code-2020:687", "civil-code-2020:697", "guarantee-2020:25", "guarantee-2020:36"],
            "supported_state": "辛的正文具有先向乙追索执行后补充清偿的意思，支持一般保证而非无条件债务加入或免责债务转移。乙未退出原债务，文书不重建借款成立时点，也不追溯改变09:20的付款归属。正文未约定辛只承担50%；通用取整条款本身不能生成该比例义务。"
          },
          {
            "id": "FINAL_SCOPE",
            "issue": "各主体即时付款请求与存续但尚不能即时执行的保证范围",
            "depends_on": ["BALANCES", "B_GUARANTEE", "C_GUARANTEE", "XIN_DOCUMENT"],
            "support_spans": ["S06", "S10", "S12", "S14"],
            "rule_refs": ["civil-code-2020:682", "civil-code-2020:687", "civil-code-2020:688", "civil-code-2020:691"],
            "supported_state": "乙承担清偿后的各项剩余债务；戊、庚各自在存续的全额连带保证范围内对应同一B余额，不形成额外债权。丁不承担所请求的合同保证履行责任。己、辛的先诉条件尚未满足，不能将其存续保证直接等同于截日应立即支付，也不能据此标记保证已经消灭。"
          }
        ],
        "output_sensitive_links": [
          {
            "from": ["B_GUARANTEE", "C_GUARANTEE"],
            "to": "SP_ALLOCATION",
            "significance": "担保是否存续决定适用双方利率比较约定还是进入其他法定抵充分支。"
          },
          {
            "from": ["C_AMOUNT"],
            "to": "SP_ALLOCATION",
            "significance": "应比较受保护的13.00%，而非C名义23.50%；该区别能够改变付款归属。"
          },
          {
            "from": ["SP_ALLOCATION"],
            "to": "BALANCES",
            "significance": "付款归属改变B、C剩余余额及相应保证覆盖金额。"
          },
          {
            "from": ["BALANCES", "XIN_DOCUMENT"],
            "to": "FINAL_SCOPE",
            "significance": "付款先于签约，后签文书的正文及先诉条件决定责任主体和即时请求边界，而非追溯重分付款。"
          }
        ]
      },
      "answerability": {
        "status": "answerable_from_supplied_materials",
        "scope": "可提取规则适用、证据去重、付款抵充及保证责任边界的主判断与依赖图；不属于原案裁判解释。",
        "basis": "关键交付、利率时点、付款状态、清偿约定、保证条款、分别行权及付款后签约事件均有明确题设定位，并附对应规范摘录。",
        "pending_checks": [
          "后续独立复算B逐次结息、整体上限和SP-01内部抵充。",
          "后续独立复算C跨利率切点的日数、各笔付款后的本金及未付利息。",
          "在答案生成前冻结分项金额口径及中间计算精度，核对最终取分和合计。",
          "独立核验所附官方来源、规范版本及摘录对应关系。"
        ],
        "release_status": "P1提取结果，不是已验收训练样本或已完成数值核验的参考答案。"
      }
    }
  ],
  "rejected_units": [],
  "limitations": [
    "全部案件事实均为显著标明的虚构题设；上述状态是依题设与所附条文建立的研究判断，不是法院查明事实或实际裁判结论。",
    "仅使用当前DATA中的正文和规范摘录；来源区的历史计数、修改假设、机制标签及参考不变声明，不作为实体答案依据。",
    "本次未访问链接、历史运行文件或冻结原文，未重新验证哈希；材料自带的verification字段不等于本次独立核验。",
    "总述称案件于2023-08-01新受理，但S10、S14明确C-诉2于2023-06-14受理且持续至截日。上述提取按具体程序记录区分C与当日新受理的A、B；下游不得将C的再诉日期改成8月1日，建议标准化时修正总述以消除歧义。",
    "不提取丁的无效保证过错赔偿定额，也不预测己、辛将来执行不能后的实际支付金额；这些事项未被当前诉请和既有事实唯一支持。",
    "当前阶段未生成题面、未接收种子、未完成盲答审计或经验难度评定。"
  ]
}
